type Reservation = { reservation_id: string | null; ro_number: string | null; status: string | null; reservation_type: string | null; requested_model: string | null; pay_type: string | null; start_date: string | null; expected_return_datetime: string | null; actual_return_datetime: string | null; billed_through_datetime: string | null }
type Customer = { customer_id: string | null; tekion_customer_number: string | null; name: string | null; phone: string | null; email: string | null }
type CurrentVehicle = { vehicle_event_id: string | null; vehicle_id: string | null; vin: string | null; vin_last8: string | null; stock_number: string | null; model_year: number | null; model: string | null; trim: string | null; fleet_type: string | null; current_tag: string | null; actual_out_at: string | null; actual_in_at: string | null; current_vehicle_contract_day: number | null }
type Segment = { billing_line_id: string; vehicle_id: string | null; vehicle_event_id: string | null; contract_period_id: string | null; pay_type_rule_id: string | null; pay_type: string | null; line_type: string; source_rule: string | null; start_time: string | null; end_time: string | null; paid_through_at: string | null; contract_days: number | null; is_open: boolean; amount: string; tax_amount: string; tax_billing_line_id: string | null; tax_line_amount: string | null; daily_rate_override: string | null; default_daily_rate_snapshot: string | null; tax_rate_snapshot: string | null; is_taxable_snapshot: boolean | null; tax_rate_source_snapshot: string | null; warranty_provider_id: string | null; default_covered_days_snapshot: number | null; covered_days_override: number | null; extended_from_billing_line_id: string | null }
type ExtendedWarranty = { case_id: string; provider_id: string | null; provider_name: string | null; default_covered_days_snapshot: number | null; approved_days: number | null; effective_covered_days: number | null; default_daily_rate_snapshot: string | null; coverage_started_at: string | null; coverage_exhausted_at: string | null; current_contract_day: number | null; post_coverage_pay_type_rule_id: string | null; requires_manual_review: boolean; can_override: boolean }
type ReadyPreview = { status: 'billing_preview_ready'; transportation_event_id: string; transportation_event_status: string; reservation_id: string; reservation_status: string; reservation_type: string; customer: Customer; vehicle: Omit<CurrentVehicle, 'vehicle_event_id'|'actual_out_at'|'actual_in_at'|'current_vehicle_contract_day'>; vehicle_event_id: string; contract_period_id: string; vehicle_out_at: string; contract_out_at: string; expected_return_at: string | null; actual_return_at: string | null; billed_through_at: string | null; current_billing_line_id: string | null; line_type: string | null; pay_type_rule_id: string; pay_type: string; vehicle_class: string | null; billing_start: string; preview_end: string; effective_at: string; contract_days: number; daily_rate: string; rate_source: string; rental_block_pricing: Record<string, unknown> | null; subtotal: string; is_taxable: boolean; tax_rate: string; tax_amount: string; tax_rate_source: string | null; tax_explanation: string | null; total: string; historical_subtotal: string; historical_tax: string; accumulated_subtotal: string; accumulated_tax: string; accumulated_total: string; segments: Segment[]; extended_warranty: ExtendedWarranty | null }
type AttentionPreview = { status: 'billing_preview_missing_dependency'|'billing_preview_missing_configuration'|'billing_preview_unavailable'; transportation_event_id: string; effective_at: string; missing_dependency?: string; missing_configuration?: string; [context: string]: unknown }
type WorkspaceItem = { transportation_event_id: string; transportation_event_status: string; source_type: string | null; source_id: string | null; expected_return_at: string | null; reservation: Reservation; customer: Customer; current_vehicle: CurrentVehicle; preview: ReadyPreview | AttentionPreview }
type Workspace = { status: 'billing_workspace_ready'; effective_at: string; case_count: number; ready_count: number; attention_count: number; accumulated_subtotal: string; accumulated_tax: string; accumulated_total: string; items: WorkspaceItem[] }
type RentalBlockPart = { days:number; amount:string; per_day_rate:string|null; blocks?:number }
type RentalBlockPricing = { segment_days:number; monthly:RentalBlockPart; weekly:RentalBlockPart; daily:RentalBlockPart; subtotal:string }
type RentalPaymentLine = { billing_line_id:string; purpose:string; line_type:string; start_at:string|null; through_at:string|null; charge:string; tax:string; total:string; rental_paid_in_full:boolean; payment_status:string; rental_paid_at:string|null; charge_days:number|null; block_pricing:RentalBlockPricing|null; payment_paid_through_at:string|null; payment_reference_type:string|null; payment_reference_number:string|null; payment_reference_missing:boolean }
type RentalPaymentState = { status:'rental_payment_state_ready'; reservation_id:string; transportation_event_id:string; lines:RentalPaymentLine[]; contractual_charge:string; contractual_tax:string; contractual_total:string; unpaid_charge:string; unpaid_tax:string; unpaid_total:string; overall_paid_in_full:boolean; current_charge:string|null; current_tax:string|null; current_total:string|null; paid_total:string|null; balance_due:string|null; current_balance_paid_in_full:boolean|null; total_charge_days:number|null; paid_charge_days:number|null; owed_charge_days:number|null; paid_through_at:string|null; expected_return_at:string|null; overdue_days:number|null; current_block_pricing:RentalBlockPricing|null }
type ClosedScope = 'all'|'rental'|'loaner'
type ClosedItem = { transportation_event_id:string;source_type:string|null;source_id:string|null;closed_at:string;expected_return_at:string|null;reservation:Reservation;preview:ReadyPreview|AttentionPreview }
type ClosedWorkspace = { status:'closed_billing_workspace_ready';date_field:'transportation_event.closed_at';date_label:'Case closed';case_scope:ClosedScope;closed_from:string|null;closed_before:string|null;limit:number;case_count:number;ready_count:number;attention_count:number;accumulated_subtotal:string;accumulated_tax:string;accumulated_total:string;items:ClosedItem[] }

const isObject=(v:unknown):v is Record<string,unknown>=>typeof v==='object'&&v!==null&&!Array.isArray(v)
const isString=(v:unknown):v is string=>typeof v==='string'
const nullableString=(v:unknown)=>v===null||isString(v)
const nullableNumber=(v:unknown)=>v===null||(typeof v==='number'&&Number.isFinite(v))
const number=(v:unknown)=>typeof v==='number'&&Number.isFinite(v)
const money=(v:unknown):v is string=>isString(v)&&/^-?(0|[1-9]\d*)(\.\d+)?$/.test(v)
function formatExactMoney(value:string):string { if(!money(value))throw new Error('Invalid monetary value');const [whole,fraction='']=value.split('.');if(fraction.length<=2)return `${whole}.${fraction.padEnd(2,'0')}`;return `${whole}.${fraction.replace(/0+$/,'').padEnd(2,'0')}` }
const maybeMoney=(v:unknown)=>v===undefined||v===null?null:money(v)?v:null
const exact=(v:Record<string,unknown>,keys:string[])=>Object.keys(v).length===keys.length&&keys.every(k=>k in v)
const strings=(o:Record<string,unknown>,keys:string[])=>keys.every(k=>isString(o[k]))
const nullableStrings=(o:Record<string,unknown>,keys:string[])=>keys.every(k=>nullableString(o[k]))

function parseBlockPart(v:unknown,allowBlocks:boolean):RentalBlockPart|null {
 if(!isObject(v)||!number(v.days)||!money(v.amount)||!nullableString(v.per_day_rate))return null
 if(allowBlocks&&v.blocks!==undefined&&!number(v.blocks))return null
 return {days:v.days as number,amount:v.amount as string,per_day_rate:v.per_day_rate as string|null,...(allowBlocks&&typeof v.blocks==='number'?{blocks:v.blocks}:{})}
}
function parseBlockPricing(v:unknown):RentalBlockPricing|null {
 if(!isObject(v)||!number(v.segment_days)||!money(v.subtotal))return null
 const monthly=parseBlockPart(v.monthly,true),weekly=parseBlockPart(v.weekly,true),daily=parseBlockPart(v.daily,false)
 if(!monthly||!weekly||!daily)return null
 return {segment_days:v.segment_days as number,monthly,weekly,daily,subtotal:v.subtotal as string}
}
function parseRentalPayment(v:unknown,eventId:string):RentalPaymentState|null {
 if(!isObject(v)||v.status!=='rental_payment_state_ready'||v.transportation_event_id!==eventId||!isString(v.reservation_id)||!Array.isArray(v.lines)||typeof v.overall_paid_in_full!=='boolean')return null
 for(const key of ['contractual_charge','contractual_tax','contractual_total','unpaid_charge','unpaid_tax','unpaid_total'])if(!money(v[key]))return null
 const enhanced='balance_due' in v
 const lines:RentalPaymentLine[]=[]
 for(const raw of v.lines){
  if(!isObject(raw)||!isString(raw.billing_line_id)||!isString(raw.purpose)||!isString(raw.line_type)||!nullableString(raw.start_at)||!nullableString(raw.through_at)||!money(raw.charge)||!money(raw.tax)||!money(raw.total)||typeof raw.rental_paid_in_full!=='boolean'||!isString(raw.payment_status)||!nullableString(raw.rental_paid_at))return null
  const block=parseBlockPricing(raw.block_pricing)
  lines.push({billing_line_id:raw.billing_line_id,purpose:raw.purpose,line_type:raw.line_type,start_at:raw.start_at as string|null,through_at:raw.through_at as string|null,charge:raw.charge,tax:raw.tax,total:raw.total,rental_paid_in_full:raw.rental_paid_in_full,payment_status:raw.payment_status,rental_paid_at:raw.rental_paid_at as string|null,charge_days:nullableNumber(raw.charge_days)?raw.charge_days as number|null:null,block_pricing:block,payment_paid_through_at:nullableString(raw.payment_paid_through_at)?raw.payment_paid_through_at as string|null:null,payment_reference_type:nullableString(raw.payment_reference_type)?raw.payment_reference_type as string|null:null,payment_reference_number:nullableString(raw.payment_reference_number)?raw.payment_reference_number as string|null:null,payment_reference_missing:typeof raw.payment_reference_missing==='boolean'?raw.payment_reference_missing:false})
 }
 if(enhanced){
  for(const key of ['current_charge','current_tax','current_total','paid_total','balance_due'])if(!money(v[key]))return null
  if(!nullableNumber(v.total_charge_days)||!nullableNumber(v.paid_charge_days)||!nullableNumber(v.owed_charge_days)||!nullableNumber(v.overdue_days)||!nullableString(v.paid_through_at)||!nullableString(v.expected_return_at)||typeof v.current_balance_paid_in_full!=='boolean')return null
 }
 return {status:'rental_payment_state_ready',reservation_id:v.reservation_id,transportation_event_id:eventId,lines,contractual_charge:v.contractual_charge as string,contractual_tax:v.contractual_tax as string,contractual_total:v.contractual_total as string,unpaid_charge:v.unpaid_charge as string,unpaid_tax:v.unpaid_tax as string,unpaid_total:v.unpaid_total as string,overall_paid_in_full:v.overall_paid_in_full,current_charge:enhanced?maybeMoney(v.current_charge):null,current_tax:enhanced?maybeMoney(v.current_tax):null,current_total:enhanced?maybeMoney(v.current_total):null,paid_total:enhanced?maybeMoney(v.paid_total):null,balance_due:enhanced?maybeMoney(v.balance_due):null,current_balance_paid_in_full:enhanced?v.current_balance_paid_in_full as boolean:null,total_charge_days:enhanced?v.total_charge_days as number:null,paid_charge_days:enhanced?v.paid_charge_days as number:null,owed_charge_days:enhanced?v.owed_charge_days as number:null,paid_through_at:enhanced?v.paid_through_at as string|null:null,expected_return_at:enhanced?v.expected_return_at as string|null:null,overdue_days:enhanced?v.overdue_days as number:null,current_block_pricing:enhanced?parseBlockPricing(v.current_block_pricing):null}
}

const segmentKeys=['billing_line_id','vehicle_id','vehicle_event_id','contract_period_id','pay_type_rule_id','pay_type','line_type','source_rule','start_time','end_time','paid_through_at','contract_days','is_open','amount','tax_amount','tax_billing_line_id','tax_line_amount','daily_rate_override','default_daily_rate_snapshot','tax_rate_snapshot','is_taxable_snapshot','tax_rate_source_snapshot','warranty_provider_id','default_covered_days_snapshot','covered_days_override','extended_from_billing_line_id']
function parseSegment(v:unknown):v is Segment { if(!isObject(v)||!exact(v,segmentKeys)||!strings(v,['billing_line_id','line_type'])||!nullableStrings(v,['vehicle_id','vehicle_event_id','contract_period_id','pay_type_rule_id','pay_type','source_rule','start_time','end_time','paid_through_at','tax_billing_line_id','tax_line_amount','daily_rate_override','default_daily_rate_snapshot','tax_rate_snapshot','tax_rate_source_snapshot','warranty_provider_id','extended_from_billing_line_id'])||!money(v.amount)||!money(v.tax_amount)||typeof v.is_open!=='boolean')return false; return (v.is_taxable_snapshot===null||typeof v.is_taxable_snapshot==='boolean')&&nullableNumber(v.contract_days)&&nullableNumber(v.default_covered_days_snapshot)&&nullableNumber(v.covered_days_override) }
const warrantyKeys=['case_id','provider_id','provider_name','default_covered_days_snapshot','approved_days','effective_covered_days','default_daily_rate_snapshot','coverage_started_at','coverage_exhausted_at','current_contract_day','post_coverage_pay_type_rule_id','requires_manual_review','can_override']
function parseWarranty(v:unknown):v is ExtendedWarranty|null { return v===null||(isObject(v)&&exact(v,warrantyKeys)&&isString(v.case_id)&&nullableStrings(v,['provider_id','provider_name','default_daily_rate_snapshot','coverage_started_at','coverage_exhausted_at','post_coverage_pay_type_rule_id'])&&['default_covered_days_snapshot','approved_days','effective_covered_days','current_contract_day'].every(k=>nullableNumber(v[k]))&&typeof v.requires_manual_review==='boolean'&&typeof v.can_override==='boolean') }
const customerKeys=['customer_id','tekion_customer_number','name','phone','email']
const vehicleKeys=['vehicle_id','vin','vin_last8','stock_number','model_year','model','trim','fleet_type','current_tag']
const readyKeys=['status','transportation_event_id','transportation_event_status','reservation_id','reservation_status','reservation_type','customer','vehicle','vehicle_event_id','contract_period_id','vehicle_out_at','contract_out_at','expected_return_at','actual_return_at','billed_through_at','current_billing_line_id','line_type','pay_type_rule_id','pay_type','vehicle_class','billing_start','preview_end','effective_at','contract_days','daily_rate','rate_source','rental_block_pricing','subtotal','is_taxable','tax_rate','tax_amount','tax_rate_source','tax_explanation','total','historical_subtotal','historical_tax','accumulated_subtotal','accumulated_tax','accumulated_total','segments','extended_warranty']
function parseReady(v:Record<string,unknown>):v is ReadyPreview { const c=v.customer,x=v.vehicle; return exact(v,readyKeys)&&v.status==='billing_preview_ready'&&strings(v,['transportation_event_id','transportation_event_status','reservation_id','reservation_status','reservation_type','vehicle_event_id','contract_period_id','vehicle_out_at','contract_out_at','pay_type_rule_id','pay_type','billing_start','preview_end','effective_at','rate_source'])&&nullableStrings(v,['expected_return_at','actual_return_at','billed_through_at','current_billing_line_id','line_type','vehicle_class','tax_rate_source','tax_explanation'])&&number(v.contract_days)&&(v.rental_block_pricing===null||isObject(v.rental_block_pricing))&&['daily_rate','subtotal','tax_rate','tax_amount','total','historical_subtotal','historical_tax','accumulated_subtotal','accumulated_tax','accumulated_total'].every(k=>money(v[k]))&&typeof v.is_taxable==='boolean'&&isObject(c)&&exact(c,customerKeys)&&nullableStrings(c,customerKeys)&&isObject(x)&&exact(x,vehicleKeys)&&nullableStrings(x,vehicleKeys.filter(k=>k!=='model_year'))&&nullableNumber(x.model_year)&&Array.isArray(v.segments)&&v.segments.every(parseSegment)&&parseWarranty(v.extended_warranty) }
function parseAttention(v:Record<string,unknown>):v is AttentionPreview { if(!['billing_preview_missing_dependency','billing_preview_missing_configuration','billing_preview_unavailable'].includes(String(v.status))||!isString(v.transportation_event_id)||!isString(v.effective_at))return false; if(v.status==='billing_preview_missing_dependency')return isString(v.missing_dependency)&&v.missing_configuration===undefined; if(v.status==='billing_preview_missing_configuration')return isString(v.missing_configuration)&&v.missing_dependency===undefined; return v.missing_dependency===undefined&&v.missing_configuration===undefined }
const reservationKeys=['reservation_id','ro_number','status','reservation_type','requested_model','pay_type','start_date','expected_return_datetime','actual_return_datetime','billed_through_datetime']
const currentVehicleKeys=['vehicle_event_id','vehicle_id','vin','vin_last8','stock_number','model_year','model','trim','fleet_type','current_tag','actual_out_at','actual_in_at','current_vehicle_contract_day']
const itemKeys=['transportation_event_id','transportation_event_status','source_type','source_id','expected_return_at','reservation','customer','current_vehicle','preview']
function parseItem(v:unknown):v is WorkspaceItem { if(!isObject(v)||!exact(v,itemKeys)||!strings(v,['transportation_event_id','transportation_event_status'])||!nullableStrings(v,['source_type','source_id','expected_return_at']))return false; const r=v.reservation,c=v.customer,x=v.current_vehicle,p=v.preview; return isObject(r)&&exact(r,reservationKeys)&&nullableStrings(r,reservationKeys)&&isObject(c)&&exact(c,customerKeys)&&nullableStrings(c,customerKeys)&&isObject(x)&&exact(x,currentVehicleKeys)&&nullableStrings(x,currentVehicleKeys.filter(k=>!['model_year','current_vehicle_contract_day'].includes(k)))&&nullableNumber(x.model_year)&&nullableNumber(x.current_vehicle_contract_day)&&isObject(p)&&(p.status==='billing_preview_ready'?parseReady(p):parseAttention(p)) }
function parseWorkspace(v:unknown):Workspace|null { const keys=['status','effective_at','case_count','ready_count','attention_count','accumulated_subtotal','accumulated_tax','accumulated_total','items']; if(!isObject(v)||!exact(v,keys)||v.status!=='billing_workspace_ready'||!isString(v.effective_at)||!number(v.case_count)||!number(v.ready_count)||!number(v.attention_count)||!money(v.accumulated_subtotal)||!money(v.accumulated_tax)||!money(v.accumulated_total)||!Array.isArray(v.items)||!v.items.every(parseItem)||v.case_count!==v.items.length||(v.ready_count as number)+(v.attention_count as number)!==v.case_count)return null; return v as Workspace }
const closedItemKeys=['transportation_event_id','source_type','source_id','closed_at','expected_return_at','reservation','preview']
function parseClosedItem(v:unknown):v is ClosedItem { if(!isObject(v)||!exact(v,closedItemKeys)||!strings(v,['transportation_event_id','closed_at'])||!nullableStrings(v,['source_type','source_id','expected_return_at'])||!isObject(v.reservation)||!exact(v.reservation,reservationKeys)||!nullableStrings(v.reservation,reservationKeys)||!isObject(v.preview))return false;return v.preview.status==='billing_preview_ready'?parseReady(v.preview):parseAttention(v.preview) }
function parseClosedWorkspace(v:unknown):ClosedWorkspace|null {const keys=['status','date_field','date_label','case_scope','closed_from','closed_before','limit','case_count','ready_count','attention_count','accumulated_subtotal','accumulated_tax','accumulated_total','items'];if(!isObject(v)||!exact(v,keys)||v.status!=='closed_billing_workspace_ready'||v.date_field!=='transportation_event.closed_at'||v.date_label!=='Case closed'||!['all','rental','loaner'].includes(String(v.case_scope))||!nullableString(v.closed_from)||!nullableString(v.closed_before)||!number(v.limit)||(v.limit as number)<1||(v.limit as number)>200||!number(v.case_count)||!number(v.ready_count)||!number(v.attention_count)||!money(v.accumulated_subtotal)||!money(v.accumulated_tax)||!money(v.accumulated_total)||!Array.isArray(v.items)||!v.items.every(parseClosedItem)||v.case_count!==v.items.length||(v.ready_count as number)+(v.attention_count as number)!==v.case_count)return null;return v as ClosedWorkspace}

const showDate=(v:string|null)=>v?new Date(v).toLocaleString():'Unavailable'
const showShortDate=(v:string|null)=>v?new Date(v).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'Unavailable'
const showShortDateTime=(v:string|null)=>v?new Date(v).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'Unavailable'
const label=(v:string)=>v.replaceAll('_',' ')
const attentionReason=(p:AttentionPreview)=>p.status==='billing_preview_missing_dependency'?label(p.missing_dependency??'required dependency unavailable'):p.status==='billing_preview_missing_configuration'?label(p.missing_configuration??'required configuration unavailable'):'Billing preview unavailable'
const isRental=(item:WorkspaceItem)=>item.reservation.reservation_type?.trim().toLowerCase()==='rental'
const segmentRate=(segment:Segment)=>segment.daily_rate_override??segment.default_daily_rate_snapshot
const isOverdue=(item:WorkspaceItem)=>{const due=item.expected_return_at??item.reservation.expected_return_datetime;if(!due||item.reservation.actual_return_datetime)return false;return new Date(due).getTime()<Date.now()}
export const ACTIVE_CASE_STORAGE_KEY='billing.activeTransportationEventId'
const rememberedActiveCase=()=>typeof window==='undefined'?null:window.sessionStorage.getItem(ACTIVE_CASE_STORAGE_KEY)
const rememberActiveCase=(id:string)=>window.sessionStorage.setItem(ACTIVE_CASE_STORAGE_KEY,id)
const forgetActiveCase=()=>window.sessionStorage.removeItem(ACTIVE_CASE_STORAGE_KEY)
const historyName=(segment:Segment)=>segment.line_type==='rental_extension'?'Extension':segment.pay_type??label(segment.line_type)

function BlockBreakdown({pricing,compact=false}:{pricing:RentalBlockPricing|null;compact?:boolean}) {
 if(!pricing)return null
 const parts:[string,RentalBlockPart][]=[['Monthly',pricing.monthly],['Weekly',pricing.weekly],['Daily',pricing.daily]]
 const visible=parts.filter(([,part])=>part.days>0)
 if(visible.length===0)return null
 return <div className={compact?'rate-blocks compact':'rate-blocks'}>{visible.map(([name,part])=><span className="rate-block" key={name}><b>{name}</b> {part.days} {part.days===1?'day':'days'}{part.per_day_rate?` × $${formatExactMoney(part.per_day_rate)}`:''} = ${formatExactMoney(part.amount)}</span>)}</div>
}

function CompactCaseCard({item,onOpen}:{item:WorkspaceItem;onOpen:()=>void}) {
 const p=item.preview
 const rental=isRental(item)
 const due=item.expected_return_at??item.reservation.expected_return_datetime
 const vehicle=[item.current_vehicle.model,item.current_vehicle.stock_number].filter(Boolean).join(' / ')||'Vehicle unavailable'
 const status=isOverdue(item)?'OVERDUE':p.status==='billing_preview_ready'?'Active':'Attention'
 const currentTotal=p.status==='billing_preview_ready'?`$${formatExactMoney(p.accumulated_total)}`:'Billing unavailable'
 return <article className={`billing-case compact-case${p.status==='billing_preview_ready'?'':' attention'}${isOverdue(item)?' overdue-case':''}`} role="button" tabIndex={0} aria-label={`Open billing case for ${item.customer.name??'customer unavailable'}`} onClick={onOpen} onKeyDown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();onOpen()}}}>
  <div className="compact-case-line"><strong>{item.customer.name??'Customer unavailable'}</strong><span>{rental?'Rental':item.reservation.ro_number?`RO #${item.reservation.ro_number}`:'Loaner'}</span><span>{vehicle}</span><span>Due {showShortDateTime(due)}</span><b>{currentTotal}</b><span className={`case-status ${status==='OVERDUE'?'overdue':''}`}>{status}</span><button type="button" onClick={event=>{event.stopPropagation();onOpen()}}>Open</button></div>
  {(p.status!=='billing_preview_ready'||isOverdue(item))&&<div className="compact-case-note">{p.status!=='billing_preview_ready'?`Attention: ${attentionReason(p)}`:`Expected return passed ${showShortDate(due)}. No automatic Extension was created.`}</div>}
 </article>
}

const checkpointKeys=['status','reservation_id','transportation_event_id','billing_line_id','billed_through_at','checkpoint_subtotal','checkpoint_tax','checkpoint_total','tax_child_result','billing_preview']
function validCheckpoint(v:unknown,item:WorkspaceItem){return isObject(v)&&exact(v,checkpointKeys)&&v.status==='billing_checkpoint_recorded'&&v.reservation_id===item.reservation.reservation_id&&v.transportation_event_id===item.transportation_event_id&&strings(v,['billing_line_id','billed_through_at'])&&['checkpoint_subtotal','checkpoint_tax','checkpoint_total'].every(k=>money(v[k]))&&isObject(v.tax_child_result)&&isObject(v.billing_preview)&&parseReady(v.billing_preview)}
const completionKeys=['status','reservation_id','completion_result','unified_case_payload']
const completionResultKeys=['status','reservation_id','transportation_event_id','actual_in_at','return_result','billing_close_result','transportation_event_close_result']
function validCompletion(v:unknown,item:WorkspaceItem,actualInAt:string){if(!isObject(v)||!exact(v,completionKeys)||v.status!=='case_completed_and_loaded'||v.reservation_id!==item.reservation.reservation_id||!isObject(v.unified_case_payload)||!isObject(v.completion_result)||!exact(v.completion_result,completionResultKeys))return false;const result=v.completion_result;return result.status==='case_returned_and_closed'&&result.reservation_id===item.reservation.reservation_id&&result.transportation_event_id===item.transportation_event_id&&isString(result.actual_in_at)&&new Date(result.actual_in_at).getTime()===new Date(actualInAt).getTime()&&isObject(result.return_result)&&(result.billing_close_result===null||isObject(result.billing_close_result))&&isObject(result.transportation_event_close_result)}
const localNow=()=>{const d=new Date(),offset=d.getTimezoneOffset();return new Date(d.getTime()-offset*60000).toISOString().slice(0,16)}
function CheckpointAction({item,onReload}:{item:WorkspaceItem;onReload:(id:string)=>Promise<unknown>}){const[at,setAt]=useState(localNow),[note,setNote]=useState(''),[preview,setPreview]=useState<ReadyPreview|null>(null),[previewAt,setPreviewAt]=useState<string|null>(null),[busy,setBusy]=useState(false),[message,setMessage]=useState<string|null>(null);const proposed=()=>{const d=new Date(at);return at&&!Number.isNaN(d.getTime())&&d.getTime()<=Date.now()?d.toISOString():null};const loadPreview=async()=>{const value=proposed();if(!value)return setMessage('Select a valid billed-through date and time.');setBusy(true);const result=await supabase.rpc('get_billing_preview_state',{p_transportation_event_id:item.transportation_event_id,p_effective_at:value});if(result.error||!isObject(result.data)||!parseReady(result.data)){setPreview(null);setPreviewAt(null);setMessage('The billed-through preview is unavailable.')}else{setPreview(result.data);setPreviewAt(value);setMessage(null)}setBusy(false)};const submit=async()=>{const value=proposed();if(!value||!preview||previewAt!==value)return setMessage('Preview this exact billed-through time before confirming.');setBusy(true);const result=await supabase.rpc('mark_case_billed_through_and_get_preview_state',{p_reservation_id:item.reservation.reservation_id,p_billed_through_at:value,p_note:note.trim()||null});if(result.error||!validCheckpoint(result.data,item)){setMessage('Billed-through state could not be updated.');setBusy(false);return}await onReload(item.transportation_event_id);setMessage('Billed-through state updated.');setPreview(null);setPreviewAt(null);setBusy(false)};return <section className="case-context"><h3>Update billed through</h3><label>Date and time<input type="datetime-local" value={at} max={localNow()} disabled={busy} onChange={e=>{setAt(e.target.value);setPreview(null);setPreviewAt(null)}}/></label><label>Optional note<textarea value={note} disabled={busy} onChange={e=>setNote(e.target.value)}/></label><button type="button" disabled={busy} onClick={()=>void loadPreview()}>Preview billed through</button>{preview&&<div className="extension-preview"><h4>Billed-through preview</h4><dl className="billing-fields"><div><dt>Contract days</dt><dd>{preview.contract_days}</dd></div><div><dt>Vehicle charges</dt><dd>${formatExactMoney(preview.subtotal)}</dd></div><div><dt>Tax</dt><dd>${formatExactMoney(preview.tax_amount)}</dd></div></dl><button type="button" className="primary-action" disabled={busy} onClick={()=>void submit()}>Confirm billed through</button></div>}{message&&<p role="status">{message}</p>}</section>}

function RentalPaymentRow({line,index,onReload,onMutation,eventId}:{line:RentalPaymentLine;index:number;onReload:()=>Promise<RentalPaymentState|null>;onMutation:()=>Promise<void>;eventId:string}) {
 const [referenceType,setReferenceType]=useState<'SO'|'RO'>(line.payment_reference_type==='RO'?'RO':'SO')
 const [referenceNumber,setReferenceNumber]=useState(line.payment_reference_number??'')
 const [busy,setBusy]=useState(false)
 const [message,setMessage]=useState<string|null>(null)
 const title=line.line_type==='rental_extension'?`Extension #${index}`:'Original Rental'
 const submit=async()=>{
  if(line.rental_paid_in_full&&line.payment_reference_missing&&!referenceNumber.trim()){setMessage('Enter an SO# or RO# to resolve the missing-reference warning.');return}
  setBusy(true);setMessage(null)
  const result=await supabase.rpc('record_rental_billing_line_payment_state',{p_billing_line_id:line.billing_line_id,p_reference_type:referenceType,p_reference_number:referenceNumber.trim()||null})
  if(result.error||!parseRentalPayment(result.data,eventId)){setMessage('The Rental payment update was not accepted.');setBusy(false);return}
  await onReload();await onMutation();setBusy(false)
 }
 return <div className={`rental-payment-row${line.payment_reference_missing?' reference-missing':''}`}>
  <div className="payment-row-main"><div><strong>{title}</strong><span>{showShortDateTime(line.start_at)} → {showShortDateTime(line.through_at)}{line.charge_days!==null?` · ${line.charge_days} ${line.charge_days===1?'day':'days'}`:''}</span></div><div className="payment-money"><span>Pre-tax <b>${formatExactMoney(line.charge)}</b></span><span>Tax <b>${formatExactMoney(line.tax)}</b></span><span>Total <b>${formatExactMoney(line.total)}</b></span></div><span className={`payment-status ${line.rental_paid_in_full?'paid':'unpaid'}`}>{line.rental_paid_in_full?'PAID':'NOT PAID'}</span></div>
  <BlockBreakdown pricing={line.block_pricing} compact />
  {line.rental_paid_in_full&&line.payment_reference_number?<div className="payment-proof">Paid {showShortDateTime(line.rental_paid_at)} · <b>{line.payment_reference_type}# {line.payment_reference_number}</b>{line.payment_paid_through_at&&<span> · Paid through {showShortDateTime(line.payment_paid_through_at)}</span>}</div>:<div className="payment-entry"><button type="button" className="reference-toggle" disabled={busy} onClick={()=>setReferenceType(type=>type==='SO'?'RO':'SO')}>{referenceType}#</button><input aria-label={`${title} ${referenceType} number`} value={referenceNumber} disabled={busy} onChange={event=>setReferenceNumber(event.target.value)} placeholder={`${referenceType} number (optional)`}/><button type="button" className={line.rental_paid_in_full?'secondary-action':'primary-action'} disabled={busy} onClick={()=>void submit()}>{busy?'Saving…':line.rental_paid_in_full?'Save Reference':'Record Payment'}</button>{line.payment_reference_missing&&<span className="missing-reference-badge">Reference missing · Warning Center</span>}</div>}
  {message&&<p className="inline-message" role="status">{message}</p>}
 </div>
}

function RentalExtensionAction({item,onReload,onMutation}:{item:WorkspaceItem;onReload:(id:string)=>Promise<unknown>;onMutation:()=>Promise<void>}) {
 const [at,setAt]=useState(''),[reason,setReason]=useState(''),[note,setNote]=useState(''),[preview,setPreview]=useState<Record<string,unknown>|null>(null),[busy,setBusy]=useState(false),[message,setMessage]=useState<string|null>(null)
 const proposed=()=>{const value=new Date(at);if(!at||Number.isNaN(value.getTime())||!reason.trim()){setMessage('Choose a later return and enter a reason.');return null}return value.toISOString()}
 const previewExtension=async()=>{const value=proposed();if(!value)return;setBusy(true);const result=await supabase.rpc('preview_rental_extension_state',{p_reservation_id:item.reservation.reservation_id,p_new_expected_return_at:value});if(result.error||!isObject(result.data)){setMessage('The Extension preview is unavailable.');setPreview(null)}else{setPreview(result.data);setMessage(null)}setBusy(false)}
 const confirm=async()=>{const value=proposed();if(!value||!preview)return;setBusy(true);const result=await supabase.rpc('accept_case_extension_and_get_unified_payload_state',{p_reservation_id:item.reservation.reservation_id,p_new_expected_return_at:value,p_extension_amount:0,p_extension_tax_amount:null,p_reason_code:reason.trim(),p_optional_note:note.trim()||null,p_entered_by_user_id:null,p_escalate_current_dependency:false});if(result.error||!isObject(result.data)){setMessage('The Rental could not be extended.');setBusy(false);return}await onReload(item.transportation_event_id);await onMutation();setMessage('Extension created. Record its payment separately when payment is received.');setPreview(null);setAt('');setReason('');setNote('');setBusy(false)}
 const exactValue=(key:string)=>preview&&isString(preview[key])?formatExactMoney(preview[key] as string):'Unavailable'
 const block=preview?parseBlockPricing(preview.block_pricing):null
 return <section className="rental-extension-panel"><h3>Extend Rental</h3><div className="extension-fields"><label>New return<input type="datetime-local" value={at} disabled={busy} onChange={event=>{setAt(event.target.value);setPreview(null)}}/></label><label>Reason<input value={reason} disabled={busy} onChange={event=>{setReason(event.target.value);setPreview(null)}} placeholder="Customer requested more time"/></label><label>Note <span>(optional)</span><input value={note} disabled={busy} onChange={event=>setNote(event.target.value)}/></label><button type="button" disabled={busy} onClick={()=>void previewExtension()}>Preview Extension</button></div>{preview&&<div className="extension-preview compact-extension-preview"><div><strong>Additional Extension</strong>{block&&<span>+ {block.segment_days} {block.segment_days===1?'day':'days'}</span>}</div><BlockBreakdown pricing={block}/><div className="extension-total"><span>Pre-tax <b>${exactValue('additional_charge')}</b></span><span>Tax <b>${exactValue('additional_tax')}</b></span><span>Total <b>${exactValue('additional_total')}</b></span><button type="button" className="primary-action" disabled={busy} onClick={()=>void confirm()}>Confirm Extension</button></div></div>}{message&&<p role="status">{message}</p>}</section>
}

function RentalCaseDetail({item,p,onBack,onReload,onComplete,onMutation}:{item:WorkspaceItem;p:ReadyPreview;onBack:()=>void;onReload:(id:string)=>Promise<unknown>;onComplete:()=>void;onMutation:()=>Promise<void>}) {
 const [payment,setPayment]=useState<RentalPaymentState|null>(null),[paymentFailed,setPaymentFailed]=useState(false)
 const loadPayment=useCallback(async()=>{const result=await supabase.rpc('get_rental_payment_state',{p_transportation_event_id:item.transportation_event_id});const parsed=result.error?null:parseRentalPayment(result.data,item.transportation_event_id);setPayment(parsed);setPaymentFailed(!parsed);return parsed},[item.transportation_event_id])
 useEffect(()=>{void loadPayment()},[loadPayment])
 const vin=item.current_vehicle.vin_last8??item.current_vehicle.vin
 const currentCharge=payment?.current_charge??p.accumulated_subtotal
 const currentTax=payment?.current_tax??p.accumulated_tax
 const currentTotal=payment?.current_total??p.accumulated_total
 const balanceDue=payment?.balance_due??payment?.unpaid_total??p.accumulated_total
 const overdue=isOverdue(item)
 const block=payment?.current_block_pricing??parseBlockPricing(p.rental_block_pricing)
 return <section className="billing-detail-view rental-detail-view">
  <button type="button" className="back-action" onClick={onBack}>← Back to active cases</button>
  <header className="rental-case-heading"><div><h2>{item.customer.name??'Customer unavailable'}</h2><p>Rental · {item.current_vehicle.model??'Model unavailable'}{item.current_vehicle.stock_number?` · ${item.current_vehicle.stock_number}`:''} · VIN ending {vin?.slice(-3)??'unavailable'}</p></div><button type="button" className="primary-action" onClick={onComplete}>Return / Complete</button></header>
  <div className="rental-timeline"><span><b>Out</b>{showShortDateTime(item.current_vehicle.actual_out_at??p.vehicle_out_at)}</span><span><b>Expected Return</b>{showShortDateTime(p.expected_return_at)}</span><span className={overdue?'overdue-text':''}><b>Status</b>{overdue?'OVERDUE — NOT EXTENDED':'Active'}</span></div>
  {overdue&&<div className="overdue-callout">Expected return passed {showShortDateTime(p.expected_return_at)}{payment?.overdue_days!==null&&payment?.overdue_days!==undefined?` · ${payment.overdue_days} ${payment.overdue_days===1?'day':'days'} overdue`:''}. No automatic Extension has been created.</div>}
  <section className="rental-summary" aria-label="Rental payment summary"><div><span>Total Days</span><strong>{payment?.total_charge_days??'—'}</strong></div><div><span>Days Paid</span><strong>{payment?.paid_charge_days??'—'}</strong></div><div><span>Paid Through</span><strong>{payment?.paid_through_at?showShortDateTime(payment.paid_through_at):'Not paid'}</strong></div><div><span>Days Owed</span><strong>{payment?.owed_charge_days??'—'}</strong></div><div className="balance"><span>Amount Owed</span><strong>${formatExactMoney(balanceDue)}</strong></div></section>
  <section className="current-charge-panel"><div className="section-title-row"><div><h3>Current Charges</h3><p>What the Rental totals if returned now.</p></div><div className="charge-totals"><span>Pre-tax <b>${formatExactMoney(currentCharge)}</b></span><span>Tax <b>${formatExactMoney(currentTax)}</b></span><span>Grand Total <b>${formatExactMoney(currentTotal)}</b></span></div></div><BlockBreakdown pricing={block}/>{block&&<div className="charged-days-total"><b>{block.segment_days}</b> days in the current pricing segment</div>}</section>
  <section className="rental-payments-panel"><div className="section-title-row"><div><h3>Payments &amp; Extensions</h3><p>Only actual customer-approved Extensions appear here. Overdue days are not Extensions.</p></div></div>{paymentFailed?<div className="attention-detail" role="alert">Authoritative Rental payment state is unavailable.</div>:!payment?<p>Loading Rental payment state…</p>:payment.lines.length===0?<p>No Rental payment periods found.</p>:<div className="rental-payment-list">{payment.lines.map((line,index)=><RentalPaymentRow key={line.billing_line_id} line={line} index={index} eventId={item.transportation_event_id} onReload={loadPayment} onMutation={async()=>{await onReload(item.transportation_event_id);await onMutation()}}/>)}</div>}</section>
  <RentalExtensionAction item={item} onReload={async id=>{await onReload(id);await loadPayment()}} onMutation={onMutation}/>
 </section>
}

function CompletionAction({item,onCancel,onComplete}:{item:WorkspaceItem;onCancel:()=>void;onComplete:()=>Promise<boolean>}){const [at,setAt]=useState(localNow),[mileage,setMileage]=useState(''),[note,setNote]=useState(''),[busy,setBusy]=useState(false),[mutationAccepted,setMutationAccepted]=useState(false),[message,setMessage]=useState<string|null>(null);const submit=async()=>{const reservation=item.reservation.reservation_id,date=new Date(at),trimmedMileage=mileage.trim();if(!reservation||!at||Number.isNaN(date.getTime())||date.getTime()>Date.now()){setMessage('Enter a valid actual return date and time that is not in the future.');return}if(trimmedMileage!==''&&!/^\d+$/.test(trimmedMileage)){setMessage('Return mileage must be a non-negative whole number or left blank.');return}const parsedMileage=trimmedMileage===''?null:Number(trimmedMileage);if(parsedMileage!==null&&(!Number.isSafeInteger(parsedMileage)||parsedMileage<0)){setMessage('Return mileage must be a non-negative whole number or left blank.');return}const actualInAt=date.toISOString();setBusy(true);setMessage(null);const result=await supabase.rpc('complete_case_and_get_unified_payload_state',{p_reservation_id:reservation,p_actual_in_at:actualInAt,p_end_mileage:parsedMileage,p_close_billing:true,p_close_note:note.trim()||null,p_closed_by:null});if(result.error||!validCompletion(result.data,item,actualInAt)){setMessage(result.error?.code==='42501'?'You do not have permission to complete and return this case.':result.error?.code==='22023'?'The return details were not accepted. Review them and try again.':'The case could not be completed. No confirmation was accepted.');setBusy(false);return}setMutationAccepted(true);const reloaded=await onComplete();if(!reloaded){setMessage('The case completed, but authoritative Billing state could not be reloaded. Return to Billing and refresh before continuing.');setBusy(false);return}setBusy(false)};const locked=busy||mutationAccepted;return <section className="billing-detail-view completion-view"><button type="button" className="back-action" disabled={busy} onClick={onCancel}>← Cancel / Return to Billing</button><p className="eyebrow">FOCUSED CASE ACTION</p><h2>Complete / Return Case</h2><p>Return the assigned vehicle, close billing, and complete this transportation case.</p><dl className="billing-fields completion-identifiers"><div><dt>RO / rental reference</dt><dd>{item.reservation.ro_number??item.reservation.reservation_type??'Unavailable'}</dd></div><div><dt>Customer</dt><dd>{item.customer.name??'Unavailable'}</dd></div><div><dt>Vehicle</dt><dd>{item.current_vehicle.model??'Unavailable'} · VIN {item.current_vehicle.vin_last8??'unavailable'}</dd></div></dl><section className="case-context"><label>Actual return date and time<input type="datetime-local" value={at} max={localNow()} disabled={locked} onChange={event=>setAt(event.target.value)}/></label><label>Optional return mileage<input type="number" min="0" step="1" inputMode="numeric" value={mileage} disabled={locked} onChange={event=>setMileage(event.target.value)}/></label><label>Optional completion note<textarea value={note} disabled={locked} onChange={event=>setNote(event.target.value)}/></label><div className="completion-actions"><button type="button" className="primary-action" disabled={locked} onClick={()=>void submit()}>Complete / Return Case</button><button type="button" disabled={busy} onClick={onCancel}>Cancel / Return to Billing</button></div>{message&&<p role={message.includes('permission')?'alert':'status'}>{message}</p>}</section></section>}
function CompletionSuccess({onReturn}:{onReturn:()=>void}){return <section className="billing-detail-view completion-success" role="status"><p className="eyebrow">CASE COMPLETE</p><h2>Case completed and vehicle returned</h2><p>Authoritative Billing state was reloaded and the closed case was removed from active cases.</p><button type="button" className="primary-action" onClick={onReturn}>Return to Billing Dashboard</button></section>}

function CustomerPayRateControl({segment,canOverride,onSaved}:{segment:Segment;canOverride:boolean;onSaved:()=>Promise<void>}) {
 const [editing,setEditing]=useState(false),[rate,setRate]=useState(segment.daily_rate_override??segment.default_daily_rate_snapshot??''),[reason,setReason]=useState(''),[busy,setBusy]=useState(false),[message,setMessage]=useState<string|null>(null)
 if(segment.pay_type?.trim().toLowerCase()!=='customer pay')return null
 const save=async(clear=false)=>{if(!clear&&!/^\d+(?:\.\d{1,2})?$/.test(rate.trim())){setMessage('Enter a non-negative daily rate with at most two decimal places.');return}setBusy(true);setMessage(null);const result=await supabase.rpc('set_customer_pay_billing_line_rate_override_state',{p_billing_line_id:segment.billing_line_id,p_daily_rate_override:clear?null:rate.trim(),p_reason:reason.trim()||null});if(result.error){setMessage(result.error.code==='42501'?'You do not have permission to change this rate.':'The authoritative rate change was not accepted.');setBusy(false);return}await onSaved();setEditing(false);setBusy(false)}
 const effective=segment.daily_rate_override??segment.default_daily_rate_snapshot
 return <section className="case-context customer-pay-rate"><h3>Customer Pay RO rate</h3><dl className="billing-fields"><div><dt>Standard daily rate</dt><dd>{segment.default_daily_rate_snapshot===null?'Unavailable':`$${formatExactMoney(segment.default_daily_rate_snapshot)}`}</dd></div><div><dt>RO override</dt><dd>{segment.daily_rate_override===null?'None':`$${formatExactMoney(segment.daily_rate_override)}`}</dd></div><div><dt>Effective daily rate</dt><dd>{effective===null?'Unavailable':`$${formatExactMoney(effective)}`}</dd></div></dl><p>Changes apply retroactively to the entire Customer Pay segment, including billed-through amounts. Update Tekion to match.</p>{canOverride&&!editing&&<div className="form-actions"><button type="button" onClick={()=>setEditing(true)}>Change Rate</button>{segment.daily_rate_override!==null&&<button type="button" disabled={busy} onClick={()=>void save(true)}>Clear Override</button>}</div>}{editing&&<div className="reservation-form"><label>Override daily rate<input inputMode="decimal" pattern="\d+(?:\.\d{1,2})?" value={rate} onChange={e=>setRate(e.target.value)}/></label><label>Reason / note (optional)<textarea value={reason} onChange={e=>setReason(e.target.value)}/></label><div className="form-actions"><button type="button" disabled={busy} onClick={()=>void save(false)}>{busy?'Saving…':'Save whole-segment rate'}</button><button type="button" disabled={busy} onClick={()=>setEditing(false)}>Cancel</button></div></div>}{message&&<p role="alert">{message}</p>}</section>
}

function LoanerCaseDetail({item,p,onBack,onReload,onComplete,canRateOverride}:{item:WorkspaceItem;p:ReadyPreview;onBack:()=>void;onReload:(id:string)=>Promise<unknown>;onComplete:()=>void;canRateOverride:boolean}) {
 const vin=item.current_vehicle.vin_last8??item.current_vehicle.vin
 return <section className="billing-detail-view"><button type="button" className="back-action" onClick={onBack}>← Back to active cases</button><header className="active-case-heading"><div><h2>{item.customer.name??'Customer unavailable'}</h2><p>{item.reservation.ro_number?`RO #${item.reservation.ro_number}`:'Vehicle'} · {item.current_vehicle.model??'Model unavailable'} · VIN ending {vin?.slice(-3)??'unavailable'}</p></div></header>{item.reservation.reservation_id&&<button type="button" className="primary-action completion-entry" onClick={onComplete}>Complete / Return Case</button>}<section className="case-context current-rental"><h3>Current case</h3><dl className="billing-fields"><div><dt>Out</dt><dd>{showDate(item.current_vehicle.actual_out_at??p.vehicle_out_at)}</dd></div><div><dt>Days in Vehicle</dt><dd>{item.current_vehicle.current_vehicle_contract_day??'Unavailable'}</dd></div><div><dt>Return</dt><dd>{showDate(p.expected_return_at)}</dd></div><div><dt>Vehicle charges</dt><dd>${formatExactMoney(p.accumulated_subtotal)}</dd></div><div><dt>Tax</dt><dd>${formatExactMoney(p.accumulated_tax)}</dd></div><div><dt>Total</dt><dd>${formatExactMoney(p.accumulated_total)}</dd></div></dl></section><CheckpointAction item={item} onReload={onReload}/>{p.segments.map(segment=><CustomerPayRateControl key={`rate-${segment.billing_line_id}`} segment={segment} canOverride={canRateOverride} onSaved={async()=>{await onReload(item.transportation_event_id)}}/>)}{p.extended_warranty&&<section className="warranty-state"><h3>Extended Warranty</h3><dl className="billing-fields"><div><dt>Provider</dt><dd>{p.extended_warranty.provider_name??'Configured provider'}</dd></div><div><dt>Covered days</dt><dd>{p.extended_warranty.effective_covered_days??'Unavailable'}</dd></div><div><dt>Coverage status</dt><dd>{p.extended_warranty.requires_manual_review?'Manual review required':'No manual review required'}</dd></div></dl></section>}<section className="segment-history"><h3>Billing history</h3>{p.segments.length===0?<p>No billing history yet.</p>:<div className="billing-history">{[...p.segments].sort((a,b)=>(a.start_time??'').localeCompare(b.start_time??'')).map(s=><div className="billing-history-item" key={s.billing_line_id}><strong>{showDate(s.start_time)} – {showDate(s.end_time??s.paid_through_at)}</strong><span>{historyName(s)} ${formatExactMoney(s.amount)} · Tax ${formatExactMoney(s.tax_amount)}</span>{segmentRate(s)&&<small>Daily rate ${formatExactMoney(segmentRate(s)!)}</small>}</div>)}</div>}</section></section>
}

function CaseDetail({item,onBack,onReload,onComplete,onMutation,canRateOverride}:{item:WorkspaceItem;onBack:()=>void;onReload:(id:string)=>Promise<unknown>;onComplete:()=>void;onMutation:()=>Promise<void>;canRateOverride:boolean}) {
 const p=item.preview
 if(p.status!=='billing_preview_ready')return <section className="billing-detail-view"><button type="button" className="back-action" onClick={onBack}>← Back to active cases</button><h2>{item.customer.name??'Customer unavailable'}</h2><div className="attention-detail" role="status"><h3>Attention required</h3><p>{attentionReason(p)}</p><p>Billing amounts are unavailable until the required operational state is present.</p></div></section>
 return isRental(item)?<RentalCaseDetail item={item} p={p} onBack={onBack} onReload={onReload} onComplete={onComplete} onMutation={onMutation}/>:<LoanerCaseDetail item={item} p={p} onBack={onBack} onReload={onReload} onComplete={onComplete} canRateOverride={canRateOverride}/>
}

const closedClassification=(item:ClosedItem)=>item.reservation.reservation_type?.toLowerCase().includes('rental')?'Rental':item.reservation.ro_number?`RO #${item.reservation.ro_number}`:'RO number unavailable'
function ClosedCard({item,onOpen}:{item:ClosedItem;onOpen:()=>void}){const p=item.preview;return <article className={`billing-case${p.status==='billing_preview_ready'?'':' attention'}`} role="button" tabIndex={0} onClick={onOpen} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onOpen()}}}><header><div><p className="case-kind">{closedClassification(item)}</p><h2>{p.status==='billing_preview_ready'?(p.customer.name??'Customer unavailable'):'Historical case'}</h2></div><span className="open-hint">Closed case <span aria-hidden="true">→</span></span><dl className="case-dates"><div><dt>Case closed</dt><dd>{showDate(item.closed_at)}</dd></div><div><dt>Expected return</dt><dd>{showDate(item.expected_return_at)}</dd></div></dl></header>{p.status==='billing_preview_ready'?<><dl className="billing-fields closed-card-context"><div><dt>Vehicle out</dt><dd>{showDate(p.vehicle_out_at)}</dd></div><div><dt>Actual return</dt><dd>{showDate(p.actual_return_at)}</dd></div><div><dt>Vehicle</dt><dd>{p.vehicle.model??'Unavailable'} · VIN {p.vehicle.vin_last8??p.vehicle.vin??'unavailable'}</dd></div></dl><div className="billing-lines"><div><span>Stored vehicle charges</span><strong>${formatExactMoney(p.accumulated_subtotal)}</strong></div><div className="tax-line"><span>Stored separate tax</span><strong>${formatExactMoney(p.accumulated_tax)}</strong></div><div className="total-line"><span>Stored combined total</span><strong>${formatExactMoney(p.accumulated_total)}</strong></div></div></>:<div className="attention-summary"><strong>Attention required</strong><span>{attentionReason(p)}</span></div>}</article>}
function ClosedDetail({item,onBack,onReload,canRateOverride}:{item:ClosedItem;onBack:()=>void;onReload:()=>Promise<void>;canRateOverride:boolean}){const p=item.preview;return <section className="billing-detail-view"><button type="button" className="back-action" onClick={onBack}>← Back to closed cases</button><p className="eyebrow">CLOSED / READ-ONLY</p><h2>{closedClassification(item)} billing history</h2><p>Dealership reconciliation with Tekion. This view does not process payments or modify the case.</p>{p.status!=='billing_preview_ready'?<div className="attention-detail"><h3>Attention required</h3><p>{attentionReason(p)}</p></div>:<><dl className="billing-fields closed-detail-fields"><div><dt>Customer</dt><dd>{p.customer.name??'Unavailable'}</dd></div><div><dt>Reservation / TE</dt><dd>{item.reservation.reservation_id??'Unavailable'} / {item.transportation_event_id}</dd></div><div><dt>Classification</dt><dd>{closedClassification(item)}</dd></div><div><dt>Vehicle / VIN / stock</dt><dd>{p.vehicle.model??'Unavailable'} / {p.vehicle.vin??'Unavailable'} / {p.vehicle.stock_number??'Unavailable'}</dd></div><div><dt>Billing start</dt><dd>{showDate(p.billing_start)}</dd></div><div><dt>Vehicle out</dt><dd>{showDate(p.vehicle_out_at)}</dd></div><div><dt>Expected return</dt><dd>{showDate(p.expected_return_at)}</dd></div><div><dt>Actual return</dt><dd>{showDate(p.actual_return_at)}</dd></div><div><dt>Case closed</dt><dd>{showDate(item.closed_at)}</dd></div><div><dt>Stored case pay type</dt><dd>{p.pay_type}</dd></div><div><dt>Rate source</dt><dd>{label(p.rate_source)}</dd></div><div><dt>Stored vehicle charges</dt><dd>${formatExactMoney(p.accumulated_subtotal)}</dd></div><div><dt>Stored separate tax</dt><dd>${formatExactMoney(p.accumulated_tax)}</dd></div><div><dt>Stored combined total</dt><dd>${formatExactMoney(p.accumulated_total)}</dd></div></dl>{p.segments.map(segment=><CustomerPayRateControl key={`closed-rate-${segment.billing_line_id}`} segment={segment} canOverride={canRateOverride} onSaved={onReload}/>)}<section className="warranty-state"><h3>Extended Warranty stored/current case context</h3>{p.extended_warranty?<dl className="billing-fields"><div><dt>Provider</dt><dd>{p.extended_warranty.provider_name??'Configured provider'}</dd></div><div><dt>Covered days</dt><dd>{p.extended_warranty.effective_covered_days??'Unavailable'}</dd></div><div><dt>Coverage exhausted</dt><dd>{showDate(p.extended_warranty.coverage_exhausted_at)}</dd></div><div><dt>Review state</dt><dd>{p.extended_warranty.requires_manual_review?'Manual review required':'No manual review required'}</dd></div></dl>:<p>Not returned for this historical case.</p>}</section><section className="segment-history"><h3>Every stored billing segment</h3>{p.segments.length===0?<p>No stored historical segments.</p>:<div className="table-wrap"><table><thead><tr><th>Pay type</th><th>Start</th><th>End / paid through</th><th>Contract days</th><th>Amount</th><th>Tax amount</th><th>Stored rate</th><th>Tax snapshot</th></tr></thead><tbody>{p.segments.map(s=><tr key={s.billing_line_id}><td>{s.pay_type??label(s.line_type)}</td><td>{showDate(s.start_time)}</td><td>{showDate(s.end_time??s.paid_through_at)}</td><td>{s.contract_days??'Unavailable'}</td><td>${formatExactMoney(s.amount)}</td><td>${formatExactMoney(s.tax_amount)}</td><td>{segmentRate(s)===null?'Unavailable':`$${formatExactMoney(segmentRate(s)!)}`}</td><td>{s.tax_rate_snapshot===null?'Unavailable':formatExactMoney(s.tax_rate_snapshot)}</td></tr>)}</tbody></table></div>}</section></>}</section>}
const throughBefore=(date:string)=>{if(!date)return null;const local=new Date(`${date}T00:00:00`);local.setDate(local.getDate()+1);return local.toISOString()}
const warningTransportationEventId=(warning:Record<string,unknown>,active:Workspace|null,closed:ClosedWorkspace|null)=>{if(isString(warning.source_id)){if(active?.items.some(item=>item.transportation_event_id===warning.source_id))return warning.source_id;if(closed?.items.some(item=>item.transportation_event_id===warning.source_id))return warning.source_id}if(isString(warning.reservation_id)){const activeMatch=active?.items.find(item=>item.reservation.reservation_id===warning.reservation_id);if(activeMatch)return activeMatch.transportation_event_id;const closedMatch=closed?.items.find(item=>item.reservation.reservation_id===warning.reservation_id);if(closedMatch)return closedMatch.transportation_event_id}if(isString(warning.contract_period_id)){const activeMatch=active?.items.find(item=>item.preview.status==='billing_preview_ready'&&item.preview.contract_period_id===warning.contract_period_id);if(activeMatch)return activeMatch.transportation_event_id;const closedMatch=closed?.items.find(item=>item.preview.status==='billing_preview_ready'&&item.preview.contract_period_id===warning.contract_period_id);if(closedMatch)return closedMatch.transportation_event_id}return null}

export function BillingWorkspace(){
 const [mode,setMode]=useState<'active'|'bulk'|'closed'>('active'),[closedState,setClosedState]=useState<ClosedWorkspace|null>(null),[scope,setScope]=useState<ClosedScope>('all'),[from,setFrom]=useState(''),[through,setThrough]=useState(''),[state,setState]=useState<Workspace|null>(null),[loading,setLoading]=useState(true),[failed,setFailed]=useState(false),[selected,setSelected]=useState<string|null>(rememberedActiveCase),[completionItem,setCompletionItem]=useState<WorkspaceItem|null>(null),[completed,setCompleted]=useState(false),[warnings,setWarnings]=useState<Record<string,unknown>[]>([]),[canRateOverride,setCanRateOverride]=useState(false)
 const loadWarnings=useCallback(async()=>{const result=await supabase.rpc('get_warning_center_detail_state');if(!result.error&&isObject(result.data)){const buckets=[result.data.critical,result.data.warning,result.data.review_needed];setWarnings(buckets.flatMap(bucket=>Array.isArray(bucket)?bucket.filter(isObject):[]))}else setWarnings([])},[])
 const load=useCallback(async(keepSelected?:string)=>{setLoading(true);setFailed(false);const result=await supabase.rpc('get_reconciled_billing_workspace_state',{p_effective_at:new Date().toISOString()});const parsed=result.error?null:parseWorkspace(result.data);setState(parsed);setSelected(current=>{const candidate=keepSelected??current;if(candidate&&parsed?.items.some(i=>i.transportation_event_id===candidate)){rememberActiveCase(candidate);return candidate}forgetActiveCase();return null});setFailed(!parsed);setLoading(false);return parsed!==null},[])
 const loadClosed=useCallback(async(nextScope:ClosedScope=scope,nextFrom:string=from,nextThrough:string=through,nextLimit=50)=>{setLoading(true);setFailed(false);const result=await supabase.rpc('get_closed_billing_workspace_state',{p_case_scope:nextScope,p_closed_from:nextFrom?new Date(`${nextFrom}T00:00:00`).toISOString():null,p_closed_before:throughBefore(nextThrough),p_limit:nextLimit});const parsed=result.error?null:parseClosedWorkspace(result.data);setClosedState(parsed);setSelected(null);forgetActiveCase();setFailed(!parsed);setLoading(false);return parsed},[from,scope,through])
 const openWarning=useCallback(async(warning:Record<string,unknown>)=>{let id=warningTransportationEventId(warning,state,closedState);if(id&&state?.items.some(item=>item.transportation_event_id===id)){setMode('active');setSelected(id);rememberActiveCase(id);return}let closed=closedState;if(!id){closed=await loadClosed('all','','',200);id=warningTransportationEventId(warning,state,closed)}if(id&&closed?.items.some(item=>item.transportation_event_id===id)){setMode('closed');setSelected(id);rememberActiveCase(id)}},[closedState,loadClosed,state])
 useEffect(()=>{void load();void loadWarnings();void supabase.rpc('get_customer_pay_rate_override_capability_state').then(result=>{setCanRateOverride(!result.error&&isObject(result.data)&&result.data.status==='customer_pay_rate_override_capability_ready'&&result.data.can_override_customer_pay_rate===true)})},[load,loadWarnings])
 const detail=state?.items.find(item=>item.transportation_event_id===selected),closedDetail=closedState?.items.find(item=>item.transportation_event_id===selected)
 return <main className="content billing-workspace"><section className="billing-heading"><div><p className="eyebrow">OPERATIONS / BILLING</p><h1>Billing Dashboard</h1><p>Rental payment and Loaner billed-through operations.</p></div><button type="button" className="primary-action" disabled={loading} onClick={()=>void(mode==='closed'?loadClosed():load())}>Refresh</button></section><nav className="billing-modes"><button type="button" onClick={()=>setMode('active')}>Active cases</button><button type="button" onClick={()=>setMode('bulk')}>Bulk Updating</button><button type="button" onClick={()=>{setMode('closed');setSelected(null);forgetActiveCase();if(!closedState)void loadClosed()}}>Closed cases</button></nav>
 {mode==='bulk'&&<BulkUpdating onApplied={load}/>} 
 {warnings.length>0&&<section className="billing-warning-strip"><h2>Warning Center</h2><div>{warnings.map((warning,index)=><button type="button" key={`${String(warning.item_type??'warning')}:${String(warning.source_id??warning.reservation_id??warning.contract_period_id??index)}:${index}`} onClick={()=>void openWarning(warning)}>{String(warning.message??'Operational warning')}</button>)}</div></section>}
 {loading&&<div className="data-message" role="status">Loading billing state…</div>}{failed&&<div className="data-message error-message" role="alert">Billing state could not be loaded. Confirm your active application account, then try again.</div>}
 {mode==='active'&&state&&!detail&&!completionItem&&!completed&&<section className="billing-metrics compact-metrics" aria-label="Billing summary">{[['Active cases',String(state.case_count)],['Billing ready',String(state.ready_count)],['Attention required',String(state.attention_count)]].map(([k,v])=><div className="metric-card" key={k}><span>{k}</span><strong>{v}</strong></div>)}</section>}
 {mode==='active'&&(completed?<CompletionSuccess onReturn={()=>setCompleted(false)}/>:completionItem?<CompletionAction item={completionItem} onCancel={()=>setCompletionItem(null)} onComplete={async()=>{const reloaded=await load();if(reloaded){forgetActiveCase();setCompletionItem(null);setCompleted(true)}return reloaded}}/>:state&&(detail?<CaseDetail item={detail} onBack={()=>{setSelected(null);forgetActiveCase()}} onReload={load} onMutation={loadWarnings} onComplete={()=>setCompletionItem(detail)} canRateOverride={canRateOverride}/>:state.case_count===0?<section className="billing-empty"><h2>No active transportation cases</h2><p>The workspace is current as of {showDate(state.effective_at)}.</p></section>:<section className="billing-cases" aria-label="Active billing cases">{state.items.map(item=><CompactCaseCard key={item.transportation_event_id} item={item} onOpen={()=>{setSelected(item.transportation_event_id);rememberActiveCase(item.transportation_event_id)}}/>)}</section>))}
 {mode==='closed'&&<>{!closedDetail&&<section className="closed-controls"><h2>Closed case filters</h2><p><strong>Case closed date (Transportation Event)</strong>. Through includes the selected local calendar day.</p><div><label>Scope<select value={scope} onChange={e=>setScope(e.target.value as ClosedScope)}><option value="all">All</option><option value="rental">Rental</option><option value="loaner">Loaner</option></select></label><label>From<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>Through<input type="date" value={through} onChange={e=>setThrough(e.target.value)}/></label><button type="button" onClick={()=>void loadClosed()}>Apply</button><button type="button" onClick={()=>{setScope('all');setFrom('');setThrough('');void loadClosed('all','','')}}>Clear</button></div><p>Showing up to 50 matching closed cases.</p></section>}{closedState&&!closedDetail&&<><section className="billing-metrics">{[['Closed cases',String(closedState.case_count)],['Ready cases',String(closedState.ready_count)],['Attention required',String(closedState.attention_count)],['Stored vehicle charges',closedState.accumulated_subtotal],['Stored separate tax',closedState.accumulated_tax],['Stored combined total',closedState.accumulated_total]].map(([k,v])=><div className="metric-card" key={k}><span>{k}</span><strong>{k.includes('cases')||k==='Attention required'?v:`$${formatExactMoney(v)}`}</strong></div>)}</section>{closedState.case_count===0?<section className="billing-empty"><h2>No matching closed cases</h2></section>:<section className="billing-cases">{closedState.items.map(item=><ClosedCard key={item.transportation_event_id} item={item} onOpen={()=>setSelected(item.transportation_event_id)}/>)}</section>}</>}{closedDetail&&<ClosedDetail item={closedDetail} onBack={()=>setSelected(null)} canRateOverride={canRateOverride} onReload={async()=>{await loadClosed()}}/>}</>}</main>
}
